package bench.web;
import bench.util.Util; import jakarta.servlet.http.*; import javax.crypto.*; import javax.crypto.spec.*; import java.io.*; import java.security.*; import java.util.*;
public class CryptoServlet extends HttpServlet { protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws IOException{ try{ byte[] key=MessageDigest.getInstance("SHA-256").digest(System.getenv().getOrDefault("APP_CRYPTO_KEY","dev-only-safe-key").getBytes()); StringBuilder sb=new StringBuilder(); for(int i=0;i<2;i++){ byte[] iv=new byte[12]; new SecureRandom().nextBytes(iv); Cipher c=Cipher.getInstance("AES/GCM/NoPadding"); c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,iv)); sb.append(Base64.getEncoder().encodeToString(c.doFinal(req.getParameter("secret").getBytes()))).append('\n'); } Util.text(resp,sb.toString()); }catch(Exception e){resp.setStatus(500);Util.text(resp,"internal error");} } }
